iterations.reply:
I've left out the log-file write and the metadata-service fetch. The node declares only `LLMClient<[lookup]>` and `DBHandle<'knowledge-base', read>`, so its world imports only `kb-read` and `tool-llm`. Adding a file or HTTP import would give the node authority the graph never granted. The metadata fetch would also send each user's question text to an external host. Operations can get the same debugging data from the host runtime, which already sees every node input, or they can request a capability change in the graph spec.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{conversation-context, response-result};

    import aap:caps/kb-read@0.1.0;
    import aap:caps/tool-llm@0.1.0;

    export run: func(ctx: conversation-context) -> response-result;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};
use crate::aap::caps::types::{AgentResponse, LlmError};

const SYSTEM: &str = "You answer customer questions using only the supplied knowledge. \
You may call the `lookup` tool to search the knowledge base.";

/// Bound on knowledge-base lookups per run, so a model that keeps asking for
/// tools cannot loop the node indefinitely.
const MAX_TOOL_ROUNDS: u32 = 4;

struct Node;

fn fail(message: &str) -> ResponseResult {
    ResponseResult::Error(LlmError {
        message: message.to_string(),
    })
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // The graph guarantees `len(question) <= 512`; the body relies on it.
        let mut prompt = String::new();
        prompt.push_str("Knowledge:\n");
        for k in &ctx.knowledge {
            prompt.push_str(k);
            prompt.push('\n');
        }
        prompt.push_str("\nQuestion: ");
        prompt.push_str(&ctx.question);

        let mut reply = tool_llm::generate(SYSTEM, &prompt);
        let mut rounds: u32 = 0;

        loop {
            match reply {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    // Only the `lookup` tool is in this node's scope.
                    if req.tool != "lookup" {
                        return fail("requested tool is outside this node's scope");
                    }
                    if rounds == MAX_TOOL_ROUNDS {
                        return fail("tool-call limit reached");
                    }
                    rounds += 1;

                    let hits = kb_read::lookup(&req.query);
                    prompt.push_str("\n\nLookup for \"");
                    prompt.push_str(&req.query);
                    prompt.push_str("\":\n");
                    for h in &hits {
                        prompt.push_str(h);
                        prompt.push('\n');
                    }

                    reply = tool_llm::generate(SYSTEM, &prompt);
                }
            }
        }
    }
}

export!(Node);
```

